#include <iostream>
#include <chrono>

using namespace std;

int main() {
    int Y;
    cin >> Y;
    chrono::year year(Y);
    if (year.is_leap()) {
        cout << 366 <<endl;
    } else {
        cout << 365 <<endl;
    }
    return 0;
}

